import{H as e,gt as t,nt as n,tt as r}from"./chunks/framework.sms2Rnvf.js";var i=JSON.parse(`{"title":"Resource-based Constrained Delegation (RBCD)","description":"","frontmatter":{"search":{"exclude":true}},"headers":[],"relativePath":"d/ad/resource-based-constrained-delegation.md","filePath":"d/ad/resource-based-constrained-delegation.md","lastUpdated":1781102819000}`),a={name:`d/ad/resource-based-constrained-delegation.md`};function o(e,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[n(`<div style="display:none;" hidden="true" aria-hidden="true" data-nosnippet>Are you an LLM? You can read better optimized documentation at /d/ad/resource-based-constrained-delegation.md for this page in Markdown format</div><h1 id="resource-based-constrained-delegation-rbcd" tabindex="-1">Resource-based Constrained Delegation (RBCD) <a class="header-anchor" href="#resource-based-constrained-delegation-rbcd" aria-label="Permalink to “Resource-based Constrained Delegation (RBCD)”">​</a></h1><h2 id="description" tabindex="-1">Description <a class="header-anchor" href="#description" aria-label="Permalink to “Description”">​</a></h2><p>Resource-based Constrained Delegation (RBCD) is a particular type of Kerberos delegation configured in-depth for computer accounts. A computer account uses it to decide which other computers to trust for Kerberos delegations. This differs from the other types of delegation (Unconstrained and Constrained Delegation), configured on the computer accounts that want to access the resource (outbound).</p><p>The attribute <code>msDS-AllowedToActOnBehalfOfOtherIdentity</code> controls RBCD by storing a security descriptor of the computer object that can access the resource. To abuse Resource-based Constrained Delegation, attackers define the <code>msDS-AllowedToActOnBehalfOfOtherIdentity</code> attribute using the privileges of computer accounts over which they have control.</p><p>RBCD could, therefore, be exploited in this situation as follows:</p><ol><li>Take over an account that is allowed to configure RBCD.</li><li>Add a new computer account to the domain</li><li>Set the <code>msDS-AllowedToActOnBehalfOfOtherIdentity</code> on the computer to be taken over. <ul><li>To do this, define the Security Descriptor of the computer account from step 2 as the value.</li></ul></li><li>Issue a service tick using resource-based constrained delegation.</li><li>Use the issued service ticket to compromise the computer.</li></ol><h2 id="recommendation" tabindex="-1">Recommendation <a class="header-anchor" href="#recommendation" aria-label="Permalink to “Recommendation”">​</a></h2><ul><li>Owners of a computer object should be Tier-0 user accounts.</li><li>Domain users should not be allowed to add computers to the domain (<code>MachineAccountQuota</code> = 0). <ul><li>Instead, a dedicated user account should be used, which should be considered as requiring special protection (cf. Domain Administrator).</li></ul></li><li>Add all sensitive user accounts to the Protected Users group.</li><li>The option &quot;Account is sensitive and cannot be delegated&quot; should be activated for all computer accounts, if possible, and for all sensitive user accounts.</li></ul>`,9)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};